        religions=['Islam ~63.5% (official religion of the Federation, predominantly Sunni Shafi\'i)', 'Buddhism ~18.7%', 'Christianity ~9.1% (widespread in Sabah and Sarawak)', 'Hinduism ~6.3%', 'Traditional Chinese religions, Sikhism, and other ~2.4%'],
